def link(r,page=None,label=None):
 url='file://'+urllib.parse.quote(r['path'],safe='/')+(f'#page={page}' if page and r['name'].endswith('.pdf') else '')
 return f'[{label or r["name"]}](<{url}>)'
def front(kind='meeting-note',status='historical',tags=None):
 return '---\ntype: '+kind+'\nupdated: 2026-09-07\nstatus: '+status+'\ntags: '+json.dumps(tags or ['LQ','meetings'],ensure_ascii=False)+'\n'
def write(name,text):
 (vault/(name+'.md')).write_text(text,encoding='utf-8')
